 ('<div class="src">\n        <div><h3>Estrellas y cielo profundo</h3><ul>\n          <li><a href="https://github.com/astronexus/HYG-Database" rel="noopener">HYG Database</a><span>posición, brillo, color y distancia de cada estrella</span></li>\n          <li><a href="https://heasarc.gsfc.nasa.gov/W3Browse/all/hipnewcat.html" rel="noopener">Hipparcos (HEASARC, NASA)</a><span>el error de cada distancia en la profundidad real</span></li>\n          <li><a href="https://github.com/Stellarium/stellarium-skycultures" rel="noopener">Stellarium · culturas del cielo</a><span>las líneas de las constelaciones (IAU)</span></li>\n          <li><a href="https://github.com/mattiaverga/OpenNGC" rel="noopener">OpenNGC</a><span>nebulosas, cúmulos y galaxias Messier, NGC e IC</span></li>\n          <li><a href="https://www.atnf.csiro.au/research/pulsar/psrcat/" rel="noopener">ATNF Pulsar Catalogue</a><span>los púlsares</span></li>\n          <li><a href="https://exoplanetarchive.ipac.caltech.edu/" rel="noopener">NASA Exoplanet Archive</a><span>las estrellas con planetas</span></li>\n          <li><a href="https://simbad.cds.unistra.fr/simbad/" rel="noopener">SIMBAD · CDS</a><span>la búsqueda de objetos por nombre</span></li>\n          <li><a href="https://svs.gsfc.nasa.gov/4851" rel="noopener">NASA SVS · Deep Star Maps (Gaia)</a><span>la Vía Láctea</span></li>\n          <li><a href="https://sky.esa.int/" rel="noopener">ESASky · DSS, SDSS y 2MASS</a><span>las fotos del cielo al hacer zoom</span></li>\n        </ul></div>\n        <div><h3>Sistema Solar y misiones</h3><ul>\n          <li><a href="https://ssd.jpl.nasa.gov/horizons/" rel="noopener">NASA JPL Horizons</a><span>planetas, cometas, sondas y telescopios</span></li>\n          <li><a href="https://ssd.jpl.nasa.gov/tools/sbdb_lookup.html" rel="noopener">JPL Small-Body Database</a><span>asteroides y cometas</span></li>\n          <li><a href="https://cneos.jpl.nasa.gov/ca/" rel="noopener">NASA CNEOS</a><span>acercamientos a la Tierra</span></li>\n          <li><a href="https://thespacedevs.com/llapi" rel="noopener">The Space Devs · Launch Library 2</a><span>los próximos lanzamientos</span></li>\n          <li><a href="https://aa.usno.navy.mil/" rel="noopener">Astronomical Almanac (USNO)</a><span>las fórmulas del Sol y la comprobación de efemérides</span></li>\n          <li><a href="https://sdo.gsfc.nasa.gov/" rel="noopener">Solar Dynamics Observatory</a><span>el Sol de hoy</span></li>\n          <li><a href="https://www.solarsystemscope.com/textures/" rel="noopener">Solar System Scope</a><span>las texturas de los planetas</span></li>\n          <li><a href="https://astrogeology.usgs.gov/" rel="noopener">USGS Astrogeology</a><span>los mapas de las lunas</span></li>\n          <li><a href="https://images.nasa.gov/" rel="noopener">NASA Image and Video Library</a><span>las imágenes de las fichas</span></li>\n        </ul></div>\n        <div><h3>Tierra, clima y relieve</h3><ul>\n          <li><a href="https://open-meteo.com/" rel="noopener">Open-Meteo</a><span>el pronóstico y las nubes por capas</span></li>\n          <li><a href="https://view.eumetsat.int/" rel="noopener">EUMETSAT · EUMETView</a><span>las nubes de Meteosat (Europa y África)</span></li>\n          <li><a href="https://registry.opendata.aws/noaa-goes/" rel="noopener">NOAA · GOES</a><span>las nubes sobre América</span></li>\n          <li><a href="https://registry.opendata.aws/noaa-himawari/" rel="noopener">JMA · Himawari (vía NOAA)</a><span>las nubes sobre Asia y Oceanía</span></li>\n          <li><a href="https://earthobservatory.nasa.gov/features/NightLights" rel="noopener">NASA GIBS · Black Marble</a><span>las luces de la noche y la contaminación lumínica</span></li>\n          <li><a href="https://registry.opendata.aws/terrain-tiles/" rel="noopener">AWS Terrain Tiles (SRTM, GMTED2010)</a><span>el relieve y el horizonte real</span></li>\n          <li><a href="https://s2maps.eu/" rel="noopener">Sentinel-2 cloudless · EOX</a><span>los colores de las montañas (Copernicus)</span></li>\n          <li><a href="https://www.ncei.noaa.gov/products/world-magnetic-model" rel="noopener">World Magnetic Model 2025 (NOAA)</a><span>la declinación de la brújula</span></li>\n          <li><a href="https://volcano.si.edu/" rel="noopener">Smithsonian · Global Volcanism Program</a><span>los volcanes y sus erupciones</span></li>\n        </ul></div>\n        <div><h3>Lugares y nombres</h3><ul>\n          <li><a href="https://www.openstreetmap.org/copyright" rel="noopener">OpenStreetMap</a><span>las cumbres y los mapas</span></li>\n          <li><a href="https://www.wikidata.org/" rel="noopener">Wikidata</a><span>montañas, volcanes y sus alturas</span></li>\n          <li><a href="https://www.geonames.org/" rel="noopener">GeoNames</a><span>los nombres de lugares al buscar</span></li>\n          <li><a href="https://opentopomap.org/" rel="noopener">OpenTopoMap</a><span>el mapa para elegir tu lugar</span></li>\n          <li><a href="https://photon.komoot.io/" rel="noopener">Photon · Komoot</a><span>la búsqueda de cumbres</span></li>\n        </ul></div>\n      </div>',
  '<div class="src">\n        <div><h3>Stars and deep sky</h3><ul>\n          <li><a href="https://github.com/astronexus/HYG-Database" rel="noopener">HYG Database</a><span>position, brightness, colour and distance of every star</span></li>\n          <li><a href="https://heasarc.gsfc.nasa.gov/W3Browse/all/hipnewcat.html" rel="noopener">Hipparcos (HEASARC, NASA)</a><span>the error of each distance in true depth</span></li>\n          <li><a href="https://github.com/Stellarium/stellarium-skycultures" rel="noopener">Stellarium · sky cultures</a><span>the constellation lines (IAU)</span></li>\n          <li><a href="https://github.com/mattiaverga/OpenNGC" rel="noopener">OpenNGC</a><span>Messier, NGC and IC nebulae, clusters and galaxies</span></li>\n          <li><a href="https://www.atnf.csiro.au/research/pulsar/psrcat/" rel="noopener">ATNF Pulsar Catalogue</a><span>pulsars</span></li>\n          <li><a href="https://exoplanetarchive.ipac.caltech.edu/" rel="noopener">NASA Exoplanet Archive</a><span>stars with planets</span></li>\n          <li><a href="https://simbad.cds.unistra.fr/simbad/" rel="noopener">SIMBAD · CDS</a><span>looking up objects by name</span></li>\n          <li><a href="https://svs.gsfc.nasa.gov/4851" rel="noopener">NASA SVS · Deep Star Maps (Gaia)</a><span>the Milky Way</span></li>\n          <li><a href="https://sky.esa.int/" rel="noopener">ESASky · DSS, SDSS and 2MASS</a><span>sky photos when you zoom in</span></li>\n        </ul></div>\n        <div><h3>Solar System and missions</h3><ul>\n          <li><a href="https://ssd.jpl.nasa.gov/horizons/" rel="noopener">NASA JPL Horizons</a><span>planets, comets, probes and telescopes</span></li>\n          <li><a href="https://ssd.jpl.nasa.gov/tools/sbdb_lookup.html" rel="noopener">JPL Small-Body Database</a><span>asteroids and comets</span></li>\n          <li><a href="https://cneos.jpl.nasa.gov/ca/" rel="noopener">NASA CNEOS</a><span>close approaches to Earth</span></li>\n          <li><a href="https://thespacedevs.com/llapi" rel="noopener">The Space Devs · Launch Library 2</a><span>upcoming launches</span></li>\n          <li><a href="https://aa.usno.navy.mil/" rel="noopener">Astronomical Almanac (USNO)</a><span>Sun formulas and ephemeris checks</span></li>\n          <li><a href="https://sdo.gsfc.nasa.gov/" rel="noopener">Solar Dynamics Observatory</a><span>today’s Sun</span></li>\n          <li><a href="https://www.solarsystemscope.com/textures/" rel="noopener">Solar System Scope</a><span>planet textures</span></li>\n          <li><a href="https://astrogeology.usgs.gov/" rel="noopener">USGS Astrogeology</a><span>maps of the moons</span></li>\n          <li><a href="https://images.nasa.gov/" rel="noopener">NASA Image and Video Library</a><span>images in the info cards</span></li>\n        </ul></div>\n        <div><h3>Earth, weather and terrain</h3><ul>\n          <li><a href="https://open-meteo.com/" rel="noopener">Open-Meteo</a><span>forecast and clouds by layer</span></li>\n          <li><a href="https://view.eumetsat.int/" rel="noopener">EUMETSAT · EUMETView</a><span>Meteosat clouds (Europe and Africa)</span></li>\n          <li><a href="https://registry.opendata.aws/noaa-goes/" rel="noopener">NOAA · GOES</a><span>clouds over the Americas</span></li>\n          <li><a href="https://registry.opendata.aws/noaa-himawari/" rel="noopener">JMA · Himawari (via NOAA)</a><span>clouds over Asia and Oceania</span></li>\n          <li><a href="https://earthobservatory.nasa.gov/features/NightLights" rel="noopener">NASA GIBS · Black Marble</a><span>night lights and light pollution</span></li>\n          <li><a href="https://registry.opendata.aws/terrain-tiles/" rel="noopener">AWS Terrain Tiles (SRTM, GMTED2010)</a><span>terrain and the real horizon</span></li>\n          <li><a href="https://s2maps.eu/" rel="noopener">Sentinel-2 cloudless · EOX</a><span>mountain colours (Copernicus)</span></li>\n          <li><a href="https://www.ncei.noaa.gov/products/world-magnetic-model" rel="noopener">World Magnetic Model 2025 (NOAA)</a><span>compass declination</span></li>\n          <li><a href="https://volcano.si.edu/" rel="noopener">Smithsonian · Global Volcanism Program</a><span>volcanoes and their eruptions</span></li>\n        </ul></div>\n        <div><h3>Places and names</h3><ul>\n          <li><a href="https://www.openstreetmap.org/copyright" rel="noopener">OpenStreetMap</a><span>peaks and maps</span></li>\n          <li><a href="https://www.wikidata.org/" rel="noopener">Wikidata</a><span>mountains, volcanoes and their heights</span></li>\n          <li><a href="https://www.geonames.org/" rel="noopener">GeoNames</a><span>place names when you search</span></li>\n          <li><a href="https://opentopomap.org/" rel="noopener">OpenTopoMap</a><span>the map to pick your place</span></li>\n          <li><a href="https://photon.komoot.io/" rel="noopener">Photon · Komoot</a><span>peak search</span></li>\n        </ul></div>\n      </div>'),
 ('<p class="src-foot">La lista completa, con la licencia y el uso de cada dato, está en <a href="https://github.com/cvasconezp/teseo/blob/main/CREDITS.md" rel="noopener">CREDITS.md</a>. ¿Viste un dato que no cuadra? <a href="https://github.com/cvasconezp/teseo/issues" rel="noopener">Cuéntanos en GitHub</a>.</p>',
  '<p class="src-foot">The full list, with the licence and use of each dataset, is in <a href="https://github.com/cvasconezp/teseo/blob/main/CREDITS.md" rel="noopener">CREDITS.md</a>. Spotted something that doesn’t add up? <a href="https://github.com/cvasconezp/teseo/issues" rel="noopener">Tell us on GitHub</a>.</p>'),
 ('<p class="kicker">5 · El hilo lo tejemos juntos</p>',
  '<p class="kicker">5 · We weave the thread together</p>'),
 ('<h3 class="sub-h">Participa en la ciencia</h3>',
  '<h3 class="sub-h">Take part in science</h3>'),
 ('<p class="soft" style="margin-top:6px">Mirar el cielo también sirve a la ciencia. Estos proyectos reciben observaciones de cualquier persona, sin ser astrónoma.</p>',
  '<p class="soft" style="margin-top:6px">Looking at the sky helps science too. These projects take observations from anyone, no astronomer needed.</p>'),
 ('<a class="btn btn--gold btn--sm" href="/#sky">Abrir el cielo en tu lugar</a>',
  '<a class="btn btn--gold btn--sm" href="/#sky">Open the sky where you are</a>'),
 ('<ul class="ticks">\n            <li><span><b>Horizonte real.</b> Tus montañas en 3D, con sus nombres y la hora en que el Sol o la Luna asoman tras ellas.</span></li>\n            <li><span><b>Monumentos.</b> Cochasquí, Machu Picchu, Teotihuacan y decenas más sobre su paisaje.</span></li>\n            <li><span><b>Tu clima.</b> Temperatura, viento y nubes por alturas, para saber cuándo salir a mirar.</span></li>\n            <li><span><b>Capas.</b> Planetas, cometas, sondas, galaxias, púlsares, exoplanetas y la contaminación lumínica.</span></li>\n          </ul>\n          <div class="tags"><span>Astronomía andina</span><span>Fichas con voz</span><span>Profundidad real de las constelaciones</span><span>Fotos 360° y postales</span></div>',
  '<ul class="ticks">\n            <li><span><b>Real horizon.</b> Your mountains in 3D, with their names and the time the Sun or Moon rises behind them.</span></li>\n            <li><span><b>Monuments.</b> Cochasquí, Machu Picchu, Teotihuacan and dozens more on their landscape.</span></li>\n            <li><span><b>Your weather.</b> Temperature, wind and clouds by altitude, to know when to go out and look.</span></li>\n            <li><span><b>Layers.</b> Planets, comets, probes, galaxies, pulsars, exoplanets and light pollution.</span></li>\n          </ul>\n          <div class="tags"><span>Andean astronomy</span><span>Cards read aloud</span><span>True depth of the constellations</span><span>360° photos and postcards</span></div>'),
 ('<div><h3>Datos oficiales y física real</h3><p>Efemérides comprobadas con la NASA y el Observatorio Naval de EE. UU.</p></div>',
  '<div><h3>Official data and real physics</h3><p>Ephemerides checked against NASA and the US Naval Observatory.</p></div>'),
 ('<div><h3>La IA narra, nunca calcula</h3><p>La IA solo describe lo que ya calculó la física.</p></div>',
  '<div><h3>AI narrates, never calculates</h3><p>AI only describes what physics has already worked out.</p></div>'),
 ('<div><h3>Tu lugar es tuyo</h3><p>Sin cuenta ni registro: tu ubicación solo sirve para calcular tu cielo.</p></div>',
  '<div><h3>Your place is yours</h3><p>No account, no sign-up: your location is only used to work out your sky.</p></div>'),
 ('<div><h3>Código abierto</h3><p>Licencia AGPL-3.0: cualquiera puede revisarlo y mejorarlo.</p></div>',
  '<div><h3>Open source</h3><p>AGPL-3.0 licence: anyone can review and improve it.</p></div>'),
 ('<li id="dato-1"><b>Las estrellas</b><span>HYG Database y Hipparcos.</span></li>',
  '<li id="dato-1"><b>The stars</b><span>HYG Database and Hipparcos.</span></li>'),
 ('<li id="dato-2"><b>Las constelaciones</b><span>Stellarium, con la Unión Astronómica Internacional.</span></li>',
  '<li id="dato-2"><b>The constellations</b><span>Stellarium, with the International Astronomical Union.</span></li>'),
 ('aria-label="2: Las constelaciones">',
  'aria-label="2: The constellations">'),
 ('<li id="dato-3"><b>Las montañas</b><span>AWS Terrain Tiles y Sentinel-2.</span></li>',
  '<li id="dato-3"><b>The mountains</b><span>AWS Terrain Tiles and Sentinel-2.</span></li>'),
 ('<li id="dato-4"><b>Los nombres de las cumbres</b><span>Wikidata y OpenStreetMap.</span></li>',
  '<li id="dato-4"><b>The peak names</b><span>Wikidata and OpenStreetMap.</span></li>'),
 ('<li id="dato-5"><b>Tu lugar</b><span>El GPS del teléfono o la búsqueda con GeoNames.</span></li>',
  '<li id="dato-5"><b>Your place</b><span>Your phone’s GPS or a GeoNames search.</span></li>'),
 ('<li id="dato-6"><b>La hora, el Sol, la Luna y los planetas</b><span>Cálculo propio, comprobado con NASA JPL Horizons.</span></li>',
  '<li id="dato-6"><b>The time, the Sun, the Moon and the planets</b><span>Worked out in the app, checked against NASA JPL Horizons.</span></li>'),
 ('<li id="dato-7"><b>Las capas</b><span>Cada una dice su fuente; las nubes, Meteosat, GOES o Himawari.</span></li>',
  '<li id="dato-7"><b>The layers</b><span>Each names its source; clouds, Meteosat, GOES or Himawari.</span></li>'),
 ('<summary>Ver las 32 fuentes</summary>',
  '<summary>See all 32 sources</summary>'),
 ('<ul class="cs-list">\n        <li><a href="https://globeatnight.org/" rel="noopener">Globe at Night</a> — cuenta estrellas y mide la contaminación lumínica</li>\n        <li><a href="https://www.zooniverse.org/" rel="noopener">Zooniverse</a> — clasifica galaxias y busca planetas</li>\n        <li><a href="https://backyardworlds.org/" rel="noopener">Backyard Worlds</a> — busca mundos cercanos al Sol</li>\n        <li><a href="https://www.aavso.org/" rel="noopener">AAVSO</a> — observa estrellas variables</li>\n        <li><a href="https://www.imo.net/" rel="noopener">Organización Internacional de Meteoros</a> — cuenta estrellas fugaces</li>\n        <li><a href="https://science.nasa.gov/citizen-science/" rel="noopener">Ciencia ciudadana de la NASA</a> — decenas de proyectos abiertos</li>\n      </ul>',
  '<ul class="cs-list">\n        <li><a href="https://globeatnight.org/" rel="noopener">Globe at Night</a> — count stars and measure light pollution</li>\n        <li><a href="https://www.zooniverse.org/" rel="noopener">Zooniverse</a> — classify galaxies and hunt for planets</li>\n        <li><a href="https://backyardworlds.org/" rel="noopener">Backyard Worlds</a> — search for worlds near the Sun</li>\n        <li><a href="https://www.aavso.org/" rel="noopener">AAVSO</a> — observe variable stars</li>\n        <li><a href="https://www.imo.net/" rel="noopener">International Meteor Organization</a> — count shooting stars</li>\n        <li><a href="https://science.nasa.gov/citizen-science/" rel="noopener">NASA citizen science</a> — dozens of open projects</li>\n      </ul>'),
 ('<p class="soft">Nació en Cayambe, en la latitud cero, de una necesidad de Killa Ñan: contar y divulgar mejor la astronomía desde una sola herramienta. Esta página sigue su hilo: desde donde estás parado hasta el fin del universo.</p>',
  '<p class="soft">It was born in Cayambe, at latitude zero, out of a need at Killa Ñan: to tell and share astronomy better from a single tool. This page follows its thread: from where you stand to the end of the universe.</p>'),
 ('<p class="soft">Teseo nació de una necesidad de Killa Ñan, la iniciativa de astronomía comunitaria que trabaja en Cayambe desde 2018: contar y divulgar mejor la astronomía desde una sola herramienta. Hoy lo usan aficionados, docentes y curiosos.</p>',
  '<p class="soft">Teseo was born out of a need at Killa Ñan, the community astronomy initiative working in Cayambe since 2018: to tell and share astronomy better from a single tool. Today amateurs, teachers and curious people use it.</p>'),
 ('<div class="social" aria-label="Redes sociales">\n            <p><b>Killa Ñan</b> <a href="https://www.instagram.com/killananec/" rel="noopener">Instagram</a> · <a href="https://www.facebook.com/share/1A65WV66FH/" rel="noopener">Facebook</a></p>\n            <p><b>Yachay Deep</b> <a href="https://www.instagram.com/yachaydeep" rel="noopener">Instagram</a> · <a href="https://www.facebook.com/yachaydeep" rel="noopener">Facebook</a> · <a href="https://x.com/yachaydeep" rel="noopener">X</a> · <a href="https://www.yachaydeep.com/" rel="noopener">Sitio web</a></p>\n            <p><b>Contacto</b> <a href="mailto:teseo@yachaydeep.com">teseo@yachaydeep.com</a> · <a href="https://wa.me/593987489892" rel="noopener">WhatsApp +593 98 748 9892</a></p>\n          </div>',
  '<div class="social" aria-label="Social media">\n            <p><b>Killa Ñan</b> <a href="https://www.instagram.com/killananec/" rel="noopener">Instagram</a> · <a href="https://www.facebook.com/share/1A65WV66FH/" rel="noopener">Facebook</a></p>\n            <p><b>Yachay Deep</b> <a href="https://www.instagram.com/yachaydeep" rel="noopener">Instagram</a> · <a href="https://www.facebook.com/yachaydeep" rel="noopener">Facebook</a> · <a href="https://x.com/yachaydeep" rel="noopener">X</a> · <a href="https://www.yachaydeep.com/" rel="noopener">Website</a></p>\n            <p><b>Contact</b> <a href="mailto:teseo@yachaydeep.com">teseo@yachaydeep.com</a> · <a href="https://wa.me/593987489892" rel="noopener">WhatsApp +593 98 748 9892</a></p>\n          </div>'),
 ('    <div class="brand">\n      <a href="/acerca" aria-label="Teseo, inicio de esta página"><b>Teseo</b></a>\n      <small>Navegación interplanetaria · <a href="https://sites.google.com/view/killanan/inicio" rel="noopener">con Killa Ñan</a></small>\n    </div>',
  '    <div class="brand">\n      <a href="/about" aria-label="Teseo, top of this page"><b>Teseo</b></a>\n      <small>Interplanetary navigation · <a href="https://sites.google.com/view/killanan/inicio" rel="noopener">with Killa Ñan</a></small>\n    </div>'),
