out = re.sub(r'<script type="application/ld\+json" id="ld-media">.*?</script>\n', '', src, flags=re.S); missing = []
for es, en in PAIRS:
    if es not in out: missing.append(es[:90]); continue
    out = out.replace(es, en)
if missing:
    sys.exit("No se encontraron estas frases en /acerca:\n  " + "\n  ".join(missing))
# comprobación: no deben quedar palabras en español visibles (letras con tilde fuera de nombres propios)
body = re.sub(r"<script.*?</script>|<style.*?</style>|<!--.*?-->|<div class=\"lang-hint\".*?</div></div>|<a class=\"lang-link\".*?</a>", "", out, flags=re.S)
leftover = [w for w in re.findall(r"[A-Za-zÁÉÍÓÚáéíóúñÑ]+", re.sub(r"<[^>]+>", " ", body))
            if re.search(r"[áéíóúñ¿]", w) and w not in {"Ñan","Vásconez","Cochasquí","Cristóbal","Español","Ecuador","español","Chichén","Itzá"}]
if leftover:
    sys.exit("Quedan palabras en español: " + ", ".join(sorted(set(leftover))))
dest = ROOT / "public/about/index.html"
if "--check" in sys.argv:
    if not dest.exists() or dest.read_text(encoding="utf-8") != out:
        sys.exit("public/about/index.html no coincide con /acerca: ejecuta python3 scripts/build_about_en.py")
    print("public/about/index.html al día"); sys.exit(0)
dest.parent.mkdir(parents=True, exist_ok=True)
dest.write_text(out, encoding="utf-8")
print("public/about/index.html generado,", len(PAIRS), "frases traducidas")
